item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "MESA item 14 requires evidence of repeated testing; reporting is insufficient."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish variation across repeated runs."
        }
      ],
      "instrument_review": "MESA item 14: Not sure. Repetition is unreported, and stability remains unknown."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing under MESA item 14."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "No repeated scores establish stability; lack of testing does not establish instability."
        }
      ],
      "instrument_review": "MESA item 14: No, because repetition was explicitly not performed. Score stability remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage reports repeated testing under the same conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "MESA item 14: Yes. The repeated results support stability for this comparison under its stated definition."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred regardless of whether its results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA item 14: Yes, because variation was tested. The findings contradict stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not supply evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation provides no repeated scores supporting stability."
        }
      ],
      "instrument_review": "MESA item 14: Not sure. Installation documentation is relevant to item 22 on reproducibility, but does not establish repetition or stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved more correct solutions in the reported grid evaluation."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA items 20 and 25 distinguish the supported grid comparison from unsupported generalization. The stated intended use stays within the evaluated puzzles."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated grid puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use supplies no evidence of performance across domains."
        }
      ],
      "instrument_review": "MESA items 2, 9 and 20: The intended use is explicit, but grid-only evidence does not establish the breadth needed to select for general intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Unmeasured safety outcomes cannot establish a safety benefit."
        }
      ],
      "instrument_review": "MESA items 16, 20 and 25: The later trial supplies comparative correctness evidence and an uncertainty interval for the intended workshop use. It does not establish safety benefits or broader applicability."
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit contradiction, and testing was distinguished from favourable results."
}
